from math import prod

def solve(inputs: dict) -> float:
    # Expect inputs with 'residues' and 'moduli', or analogous keys.
    residues = inputs.get('residues', inputs.get('a', inputs.get('r')))
    moduli = inputs.get('moduli', inputs.get('m', inputs.get('n')))
    if residues is None or moduli is None:
        # Try a few common structured fallbacks
        if len(inputs) == 2:
            vals = list(inputs.values())
            residues, moduli = vals[0], vals[1]
        else:
            raise ValueError('Missing residues/moduli')
    residues = list(map(int, residues))
    moduli = list(map(int, moduli))

    M = 1
    for m in moduli:
        M *= m

    x = 0
    for a_i, m_i in zip(residues, moduli):
        M_i = M // m_i
        inv = pow(M_i, -1, m_i)
        x = (x + a_i * M_i * inv) % M
    return float(x)

