def solve(inputs: dict) -> float:
    # Generic solver for affine recurrence iterations modulo m.
    # Expected keys: s0, a, b, m, n (or close variants).
    s = inputs.get('s0', inputs.get('s'))
    a = inputs.get('a')
    b = inputs.get('b')
    m = inputs.get('m', inputs.get('mod'))
    n = inputs.get('n', inputs.get('steps', inputs.get('k')))
    if None in (s, a, b, m, n):
        # fallback for positional-like dicts
        vals = list(inputs.values())
        if len(vals) >= 5:
            s, a, b, m, n = vals[:5]
        else:
            raise ValueError('Missing parameters')
    s = int(s); a = int(a); b = int(b); m = int(m); n = int(n)
    for _ in range(n):
        s = (a * s + b) % m
    return float(s)

